  "The number of particles in one mole.": {
  "es": "El número de partículas que hay en un mol.",
  "ar": "عدد الجسيمات في مول واحد.",
  "zh": "一摩尔物质中的粒子数。",
  "sw": "Idadi ya chembe katika mole moja.",
  "sv": "Antalet partiklar i en mol."
},
  "Astronomical unit": {
  "es": "Unidad astronómica",
  "ar": "الوحدة الفلكية",
  "zh": "天文单位",
  "sw": "Kizio cha kiastronomia",
  "sv": "Astronomisk enhet"
},
  "The average Earth–Sun distance, about 150 million km.": {
  "es": "La distancia media entre la Tierra y el Sol, unos 150 millones de km.",
  "ar": "متوسط المسافة بين الأرض والشمس، نحو 150 مليون كم.",
  "zh": "地球与太阳的平均距离，约 1.5 亿千米。",
  "sw": "Wastani wa umbali kati ya Dunia na Jua, takriban km milioni 150.",
  "sv": "Medelavståndet mellan jorden och solen, ungefär 150 miljoner km."
},
  "Light-year": {
  "es": "Año luz",
  "ar": "السنة الضوئية",
  "zh": "光年",
  "sw": "Mwaka wa mwanga",
  "sv": "Ljusår"
},
  "The distance light travels in a year — about 9.5 trillion km.": {
  "es": "La distancia que recorre la luz en un año: unos 9,5 billones de km.",
  "ar": "المسافة التي يقطعها الضوء في سنة — نحو 9.5 تريليون كم.",
  "zh": "光在一年内传播的距离——约 9.5 万亿千米。",
  "sw": "Umbali ambao mwanga husafiri kwa mwaka — takriban km trilioni 9.5.",
  "sv": "Sträckan ljuset färdas på ett år — ungefär 9,5 biljoner km."
},
  "Parsec": {
  "es": "Pársec",
  "ar": "الفرسخ الفلكي",
  "zh": "秒差距",
  "sw": "Parseki",
  "sv": "Parsec"
},
  "About 3.26 light-years.": {
  "es": "Unos 3,26 años luz.",
  "ar": "نحو 3.26 سنة ضوئية.",
  "zh": "约 3.26 光年。",
  "sw": "Takriban miaka ya mwanga 3.26.",
  "sv": "Ungefär 3,26 ljusår."
},
  "Hubble constant": {
  "es": "Constante de Hubble",
  "ar": "ثابت هابل",
  "zh": "哈勃常数",
  "sw": "Kiisibadilika cha Hubble",
  "sv": "Hubblekonstanten"
},
  "km/s per megaparsec": {
  "es": "km/s por megapársec",
  "ar": "كم/ث لكل ميغافرسخ",
  "zh": "千米/秒/百万秒差距",
  "sw": "km/s kwa kila megaparseki",
  "sv": "km/s per megaparsec"
},
  "How fast the universe expands. Measurements disagree (about 67 vs 73) — the “Hubble tension”.": {
  "es": "Lo rápido que se expande el universo. Las mediciones no coinciden (unos 67 frente a 73): la “tensión de Hubble”.",
  "ar": "مدى سرعة تمدد الكون. القياسات مختلفة (نحو 67 مقابل 73) — وهو ما يُعرف بـ«توتر هابل».",
  "zh": "宇宙膨胀的速度。不同测量结果不一致（约 67 对 73）——即“哈勃张力”。",
  "sw": "Jinsi ulimwengu unavyopanuka haraka. Vipimo havikubaliani (takriban 67 dhidi ya 73) — “mvutano wa Hubble”.",
  "sv": "Hur snabbt universum expanderar. Mätningarna går isär (ungefär 67 mot 73) — ”Hubblespänningen”."
},
