  "Each row of the bar is on a logarithmic scale: from the smallest meaningful length to the edge of what we can see is about 62 powers of ten.": {
  "es": "Cada fila de la barra está en escala logarítmica: de la longitud más pequeña con sentido al borde de lo que podemos ver hay unas 62 potencias de diez.",
  "ar": "كل صف من الشريط بمقياس لوغاريتمي: من أصغر طول له معنى إلى حافة ما يمكننا رؤيته نحو 62 قوة للعشرة.",
  "zh": "每一行的条形都是对数比例：从最小的有意义长度到我们能看到的边缘，大约跨越 62 个数量级。",
  "sw": "Kila mstari wa upau uko kwenye kipimo cha logariti: kutoka urefu mdogo kabisa wenye maana hadi ukingo wa tunachoweza kuona ni takriban vipeo 62 vya kumi.",
  "sv": "Varje rad i stapeln är i logaritmisk skala: från den minsta meningsfulla längden till kanten av det vi kan se är det ungefär 62 tiopotenser."
},
