  "A car at 100 km/h would take {0}; the fastest spacecraft so far (Parker Solar Probe, about 690,000 km/h) {1}.": {
  "es": "Un coche a 100 km/h tardaría {0}; la nave más rápida hasta ahora (Parker Solar Probe, unos 690 000 km/h), {1}.",
  "ar": "ستستغرق سيارة بسرعة 100 كم/س {0}؛ وأسرع مركبة فضائية حتى الآن (مسبار باركر الشمسي، نحو 690,000 كم/س) {1}.",
  "zh": "以 100 千米/时行驶的汽车需要 {0}；迄今最快的航天器（帕克太阳探测器，约 69 万千米/时）需要 {1}。",
  "sw": "Gari linalokwenda km 100 kwa saa lingechukua {0}; chombo cha anga chenye kasi zaidi hadi sasa (Parker Solar Probe, takriban km 690,000 kwa saa) {1}.",
  "sv": "En bil i 100 km/h skulle behöva {0}; den snabbaste rymdfarkosten hittills (Parker Solar Probe, ungefär 690 000 km/h) {1}."
},
  "{0} milliseconds": {
  "es": "{0} milisegundos",
  "ar": "{0} ملي ثانية",
  "zh": "{0} 毫秒",
  "sw": "milisekunde {0}",
  "sv": "{0} millisekunder"
},
  "So when you look at it, you see it as it was {0} ago.": {
  "es": "Así que, cuando lo miras, lo ves como era hace {0}.",
  "ar": "لذلك عندما تنظر إليه تراه كما كان قبل {0}.",
  "zh": "所以当你看着它时，你看到的是它 {0} 前的样子。",
  "sw": "Kwa hiyo unapokitazama, unakiona kama kilivyokuwa {0} iliyopita.",
  "sv": "Så när du tittar på det ser du det som det var för {0} sedan."
},
