  "= {0} kWh — enough to run a home using 4,000 kWh a year for {1}.": {
  "es": "= {0} kWh: suficiente para abastecer un hogar que usa 4000 kWh al año durante {1}.",
  "ar": "= {0} كيلوواط ساعة — تكفي لتشغيل منزل يستهلك 4,000 كيلوواط ساعة سنويًا مدة {1}.",
  "zh": "= {0} 千瓦时——足够一个每年用电 4000 千瓦时的家庭使用 {1}。",
  "sw": "= kWh {0} — inatosha kuendesha nyumba inayotumia kWh 4,000 kwa mwaka kwa {1}.",
  "sv": "= {0} kWh — nog för ett hem som använder 4 000 kWh om året i {1}."
},
  "= {0} tonnes of TNT ({1} × the Hiroshima bomb).": {
  "es": "= {0} toneladas de TNT ({1} × la bomba de Hiroshima).",
  "ar": "= {0} طن من مادة TNT ‏({1} × قنبلة هيروشيما).",
  "zh": "= {0} 吨 TNT（相当于 {1} 颗广岛原子弹）。",
  "sw": "= tani {0} za TNT ({1} × bomu la Hiroshima).",
  "sv": "= {0} ton trotyl ({1} × Hiroshimabomben)."
},
  "Real reactions release only a small part of this: fission turns about 0.1% of the mass into energy, fusion in the Sun about 0.7%, matter meeting antimatter 100%.": {
  "es": "Las reacciones reales liberan solo una pequeña parte: la fisión convierte en energía alrededor del 0,1 % de la masa, la fusión en el Sol cerca del 0,7 %, y la materia que se encuentra con antimateria el 100 %.",
  "ar": "التفاعلات الحقيقية لا تطلق إلا جزءًا صغيرًا من ذلك: الانشطار يحوّل نحو 0.1% من الكتلة إلى طاقة، والاندماج في الشمس نحو 0.7%، والتقاء المادة بالمادة المضادة 100%.",
  "zh": "真实反应只释放其中一小部分：核裂变把约 0.1% 的质量变成能量，太阳中的核聚变约 0.7%，物质与反物质相遇则是 100%。",
  "sw": "Athari halisi hutoa sehemu ndogo tu ya hii: mgawanyiko hugeuza takriban 0.1% ya masi kuwa nishati, muunganiko kwenye Jua takriban 0.7%, maada ikikutana na maada-kinyume 100%.",
  "sv": "Verkliga reaktioner frigör bara en liten del av detta: fission gör om ungefär 0,1 % av massan till energi, fusionen i solen ungefär 0,7 %, materia som möter antimateria 100 %."
},
